import{_ as e,o,c as d,ag as a}from"./chunks/framework.BaNuf0sO.js";const m=JSON.parse('{"title":"FormSelect（选择器）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/form/docs/README-FormSelect.md","filePath":"docs/core/src/components/form/docs/README-FormSelect.md"}'),l={name:"docs/core/src/components/form/docs/README-FormSelect.md"};function c(r,t,i,s,n,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="formselect-选择器" tabindex="-1">FormSelect（选择器） <a class="header-anchor" href="#formselect-选择器" aria-label="Permalink to &quot;FormSelect（选择器）&quot;">​</a></h1><blockquote><p>el-select 包装（本地 options / 远程搜索 remoteMethod / 异步 getOptions）+ option 插槽自定义渲染 + 影分身（<code>shadowClone</code> 表头漏斗，点击 popover 弹选择器，同一 v-model 同源同步）。 范式页：<code>apps/reference/src/pages/list-layout/sort/</code>（状态列表头漏斗弹选择器）。</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>配置化表单的选择字段</strong>：FormMain / FormSearch 配置接入（<code>render: FormSelect</code>），options 业务注入</li><li><strong>远程搜索</strong>：<code>remoteMethod</code> 传入即自动开 filterable + remote（输入触发远程查询）</li><li><strong>异步取选项</strong>：<code>getOptions</code> 挂载后拉取</li><li><strong>何时不用</strong>：静态小选项集用原生 el-select 即可</li></ul><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">FormSelect</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> v-model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;status&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[{ label: &#39;启用&#39;, value: 1 }, { label: &#39;禁用&#39;, value: 0 }]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li><code>options</code>（本地静态）/ <code>remoteMethod</code>（远程搜索）/ <code>getOptions</code>（异步拉取）三选一提供选项源</li><li><code>modelValue</code> = <code>OptionItem[&quot;value&quot;]</code>；选中项经 <code>detailChange</code> 上抛完整选项（immediate 首发）</li><li><code>option</code> 插槽自定义选项渲染（<code>{ data }</code> 作用域）</li><li>其余 props / 事件全量 <code>$attrs</code> 透传 el-select（placeholder / clearable / size 等）</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>默认即够用：options + v-model 即为完整选择器</strong>。以下按需开：</li><li><code>remoteMethod</code>：远程搜索（自动 filterable + remote，输入触发查询）</li><li><code>getOptions</code>：挂载后异步拉取选项</li><li><code>itemCls</code>：选项类名</li><li><strong>影分身（表头漏斗）用 <code>FormSelectShadowClone</code></strong>（本组件 + 影分身包装，薄包装纯粹性）：列表页表格头预埋容器内显示漏斗图标，点击 popover 弹选择器，同一 v-model 与本体同源同步（与 FormInputShadowClone 统一漏斗语义：「表头漏斗 = 点这里筛选」）</li></ul><h2 id="依赖关系" tabindex="-1">依赖关系 <a class="header-anchor" href="#依赖关系" aria-label="Permalink to &quot;依赖关系&quot;">​</a></h2><ul><li>form 族内部组件，无跨族依赖（仅透传 el-select）；影分身版 <code>FormSelectShadowClone</code> 依赖内部件 <code>FormShadowCloneDispatch</code> → display 族 <code>ShadowClone</code>（详见 README-FormShadowCloneDispatch.md）</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>modelValue</code></td><td><code>OptionItem[&quot;value&quot;]</code></td><td>—</td><td>v-model</td></tr><tr><td><code>options</code></td><td><code>OptionItem[]</code></td><td><code>[]</code></td><td>本地选项集</td></tr><tr><td><code>remoteMethod</code></td><td><code>(query?) =&gt; Promise&lt;OptionItem[]&gt;</code></td><td>—</td><td>远程搜索（自动 filterable + remote）</td></tr><tr><td><code>itemCls</code></td><td><code>string</code></td><td>—</td><td>选项类名</td></tr><tr><td><code>getOptions</code></td><td><code>() =&gt; Promise&lt;OptionItem[]&gt;</code></td><td>—</td><td>挂载后异步拉取选项</td></tr><tr><td>其余</td><td>—</td><td>—</td><td>全量 <code>$attrs</code> 透传 el-select（placeholder / clearable / size 等）</td></tr></tbody></table><h3 id="formselectshadowclone-影分身版" tabindex="-1">FormSelectShadowClone（影分身版） <a class="header-anchor" href="#formselectshadowclone-影分身版" aria-label="Permalink to &quot;FormSelectShadowClone（影分身版）&quot;">​</a></h3><blockquote><p>内部经 <code>FormShadowCloneDispatch</code> 实现：default 与 clone 两插槽各写一份 <code>&lt;FormSelect v-model=&quot;同一值&quot; /&gt;</code> 同源绑定驱动双处视图一致；高亮判定在<strong>本组件内部</strong>（默认规则 + <code>isHighlighted</code> 覆盖）→ 经 dispatch <code>highlighted</code> 展示在漏斗 + 插槽作用域暴露。</p></blockquote><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>modelValue</code></td><td><code>OptionItem[&quot;value&quot;]</code></td><td>—</td><td>v-model（透传 FormSelect；本体与分身弹层同源）</td></tr><tr><td><code>shadowClone</code></td><td><code>boolean</code></td><td><code>false</code></td><td>影分身开关（本体 + 分身 label+漏斗，点击 popover 弹选择器，同一 v-model 同源同步）</td></tr><tr><td><code>teleportTo</code></td><td><code>string | Element</code></td><td>—</td><td>分身目标容器（表头预埋唯一选择器；<code>shadowClone</code> 时生效，未配置不分身）</td></tr><tr><td><code>label</code></td><td><code>string</code></td><td>—</td><td>分身位字段文字（表头列名；label + 漏斗整块展示、高亮整块——表格 headerRender 只需留 teleportTo 容器，列名由分身自带）</td></tr><tr><td><code>isHighlighted</code></td><td><code>(value: unknown) =&gt; boolean</code></td><td>默认判定</td><td>分身高亮判定方法（非必传），入参 modelValue；默认 = 非 <code>null</code> / 非 <code>undefined</code> / 非空字符串 → 高亮（label + 漏斗整块）</td></tr><tr><td>其余</td><td>—</td><td>—</td><td>全量 <code>$attrs</code> 透传 FormSelect（options/remoteMethod/option 插槽等能力完整继承）</td></tr></tbody></table><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>载荷</th><th>语义</th></tr></thead><tbody><tr><td><code>update:modelValue</code></td><td><code>OptionItem[&quot;value&quot;]</code></td><td>v-model 上抛（本体与分身弹层同源）</td></tr><tr><td><code>detailChange</code></td><td><code>OptionItem | undefined</code></td><td>选中项详情变更（immediate 首发）</td></tr><tr><td>其余</td><td>el-select events</td><td><code>$attrs</code> 透传（change / blur 等）</td></tr></tbody></table><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>语义</th></tr></thead><tbody><tr><td><code>option</code></td><td>选项自定义渲染（<code>{ data }</code> 作用域；本体与分身弹层内选择器共用）</td></tr></tbody></table>',23)])])}const u=e(l,[["render",c]]);export{m as __pageData,u as default};
